<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router'
import { ElButton, ElCascader, ElCheckbox, ElCheckboxGroup, ElInput, ElMessage, ElMessageBox, ElOption, ElSelect } from 'element-plus'
import { ArrowLeft, ArrowRight, Check, CircleCheck, Save, ChevronDown, ChevronRight } from 'lucide-vue-next'
import { REGION_OPTIONS, useCommerceStore } from '@/stores/commerce'
import { newProduct, syncSupplyFields, useProductsStore, validSupplyPrice, type Product, type Supply } from '@/stores/products'
import SupplyFields from './SupplyFields.vue'
import { submitApprovals } from './productApprovals'
import ProductRichText from './ProductRichText.vue'
import { hasProductDetail, productDetailTextLength } from './productRichHtml'
import ProductMediaFields from './ProductMediaFields.vue'
import ProductSubmitPreview from './ProductSubmitPreview.vue'
import { resolveDemoImage } from '@/utils/demoMedia'
import { useOnboardingStore } from '@/stores/onboarding'
const route=useRoute(),router=useRouter(),store=useProductsStore(),commerce=useCommerceStore(),onboarding=useOnboardingStore()
const original=store.products.find(p=>p.id===route.params.id);const product=reactive<Product>(original?{...newProduct(),...JSON.parse(JSON.stringify(original)),...JSON.parse(JSON.stringify(original.editDraft||{}))}:newProduct());const step=ref(1),expanded=ref<string[]>([]),syncParks=ref<string[]>([]),syncFields=ref<string[]>([])
const missingProduct=computed(()=>!!route.params.id && !store.products.some(p=>p.id===route.params.id))
function validEditTarget(){if(route.params.id && (missingProduct.value || product.id!==route.params.id)){ElMessage.warning('商品不存在，请返回商品管理');return false}return true}
const savedState=ref(JSON.stringify(product))
const isDirty=computed(()=>step.value<5 && JSON.stringify(product)!==savedState.value)
function beforeUnload(event:BeforeUnloadEvent){if(isDirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload))
onUnmounted(()=>window.removeEventListener('beforeunload',beforeUnload))
async function confirmLeave(){if(missingProduct.value||!isDirty.value)return true;try{await ElMessageBox.confirm('商品有未保存的修改，是否保存草稿后离开？','保存修改',{confirmButtonText:'保存草稿',cancelButtonText:'放弃修改',showClose:true,distinguishCancelAndClose:true,type:'warning'});return save()}catch(action){return action==='cancel'}}
onBeforeRouteLeave(()=>confirmLeave())
onBeforeRouteUpdate(()=>confirmLeave())
const scrollArea = ref<HTMLElement | null>(null)
watch(step, () => { if (scrollArea.value) scrollArea.value.scrollTop = 0 })
const headings = ['基础信息','供货与价格','图文详情','提交预览','提交完成']
const fields=[['leadDays','货期'],['minimum','最小起售量'],['increment','递增量'],['stock','库存'],['tax','税点'],['cost','采购价'],['original','原价'],['promotion','优惠方案（类型及对应数值）']]
const parks=computed(()=>commerce.joinedParks)
// 历史商品使用自由文本存储销售区域；将已有路径补入选项，避免编辑时丢失。
type RegionOption = { value: string; label: string; children?: RegionOption[] }
const salesRegions = computed(() => (product.salesArea || '').split(/[、,，;；]/).map(area => area.split('/').map(part => part.trim()).filter(Boolean)).filter(path => path.length))
const salesRegionOptions = computed<RegionOption[]>(() => {
  const options: RegionOption[] = [{ value: '全国', label: '全国' }, ...JSON.parse(JSON.stringify(REGION_OPTIONS))]
  for (const path of salesRegions.value) {
    let nodes = options
    for (const [index, name] of path.entries()) {
      let node = nodes.find(item => item.value === name)
      if (!node) { node = { value: name, label: name }; nodes.push(node) }
      if (index < path.length - 1) { node.children ||= []; nodes = node.children }
    }
  }
  return options
})
function changeSalesRegions(value: unknown) {
  const paths = Array.isArray(value) ? value as string[][] : []
  const includesNationwide = paths.some(path => path[0] === '全国')
  const hadNationwide = salesRegions.value.some(path => path[0] === '全国')
  const selected = includesNationwide ? (hadNationwide && paths.length > 1 ? paths.filter(path => path[0] !== '全国') : [['全国']]) : paths
  product.salesArea = selected.map(path => path.join(' / ')).join('、')
}
watch(()=>product.parkIds.slice(), ids=>{for(const id of ids)if(!product.parks[id])product.parks[id]=JSON.parse(JSON.stringify(product.supply));syncParks.value=syncParks.value.filter(id=>ids.includes(id))})
function applyUnifiedTax(){for(const id of product.parkIds)if(product.parks[id])product.parks[id].tax=product.supply.tax}
const taxMismatch=computed(()=>product.parkIds.some(id=>product.parks[id] && product.parks[id].tax!==product.supply.tax))
const requiresTaxSync=computed(()=>taxMismatch.value && (!original || original.status==='draft' || original.supply.tax!==product.supply.tax || product.parkIds.some(id=>original.parks[id]?.tax!==product.parks[id]?.tax)))
function addAttribute(){product.attrs?.push({id:crypto.randomUUID(),name:'',value:''})}
function toggle(id:string){expanded.value=expanded.value.includes(id)?expanded.value.filter(x=>x!==id):[...expanded.value,id]}
async function sync(){const hasTax=syncFields.value.includes('tax');const otherFields=syncFields.value.filter(field=>field!=='tax');if(!syncFields.value.length || (otherFields.length && !syncParks.value.length)){ElMessage.warning(otherFields.length?'请选择其他字段的目标园区':'请选择要同步的字段');return}const details=[hasTax?`税点将同步至全部 ${product.parkIds.length} 个已选发布园区`:'',otherFields.length?`其他所选字段将同步至 ${syncParks.value.length} 个目标园区`:''].filter(Boolean).join('；');try{await ElMessageBox.confirm(`${details}。确认继续？`,'确认同步',{confirmButtonText:'确认同步',cancelButtonText:'取消',type:'warning'})}catch{return}if(hasTax)applyUnifiedTax();if(otherFields.length)syncSupplyFields(product,syncParks.value,otherFields);ElMessage.success('已同步所选字段')}
function validBasic(){return !!(product.name.trim()&&product.category.trim()&&(onboarding.draft.brands.length===0||!!product.brand.trim())&&product.sku.trim()&&product.unit.trim()&&product.spec?.trim()&&product.taxCode?.trim()&&!(product.attrs||[]).some(a=>!!a.name.trim()!==!!a.value.trim()))}
function validSupply(s:Supply){return [s.leadDays,s.minimum,s.increment,s.stock].every(n=>typeof n==='number'&&Number.isFinite(n)&&n>=0)&&s.minimum>=1&&s.increment>=1&&validSupplyPrice(s)}
async function hasUsableCover(){const source=product.cover&&await resolveDemoImage(product.cover).catch(()=>'');if(!source)return false;return await new Promise<boolean>(resolve=>{const image=new Image();image.onload=()=>resolve(true);image.onerror=()=>resolve(false);image.src=source})}
async function next(){if(route.params.id){step.value++;return}if(step.value===1&&!validBasic()){ElMessage.warning('请填写商品标题、类目、品牌、供应商 SKU、规格、计量单位和税收分类编码');return}if(step.value===3&&productDetailTextLength(product.description)>5000){ElMessage.warning('商品详情文字不能超过 5000 字');return}if(step.value===3&&(!(await hasUsableCover())||!hasProductDetail(product.description))){ElMessage.warning('请上传可用的商品主图并填写商品详情');return}if(step.value===2&&!product.parkIds.length){ElMessage.warning('请选择发布园区');return}if(step.value===2&&requiresTaxSync.value){ElMessage.warning('请先统一各园区税点');return}if(step.value===2&&(!validSupply(product.supply)||product.parkIds.some(id=>!product.parks[id]||!validSupply(product.parks[id])))){ElMessage.warning('请检查默认值及各园区供货、价格字段');return}step.value++}
function save(){if(!validEditTarget())return false;try{store.saveEditDraft(product);savedState.value=JSON.stringify(product);ElMessage.success('草稿已保存');return true}catch{ElMessage.error('保存失败，请重试');return false}}
function fillDemo(){const ids=parks.value.slice(0,2).map(p=>p.id);Object.assign(product,{name:'工业安全防护帽',category:onboarding.draft.businessCategories[0]||'个人防护 / 安全防护',brand:onboarding.draft.brands[0]?.name||'3M',sku:'SKU-DEMO-1001',unit:'顶',model:'M-100',spec:'标准款',taxCode:'1090407010000000000',contractName:'工业防护用品',features:'适用于园区企业日常安全防护。',salesArea:'上海市 / 浦东新区',description:'安全防护帽，适用于施工及日常作业场景。',cover:'/demo-product-helmet.svg',parkIds:ids,parks:Object.fromEntries(ids.map(id=>[id,{...product.supply}]))});ElMessage.success('演示内容已填入，可继续修改')}
async function continuePublish(){
  await router.replace(`/product/new?demo=${Date.now()}`)
  Object.assign(product,newProduct(),{code:undefined,sales:undefined,parkStatuses:undefined,parkRejectionReasons:undefined,editDraft:undefined,pendingEdit:undefined,pendingPrice:undefined,approvalLog:undefined,priceHistory:undefined})
  expanded.value=[];syncParks.value=[];syncFields.value=[];step.value=1;savedState.value=JSON.stringify(product)
}
async function submit(){if(!validEditTarget())return;if(requiresTaxSync.value){ElMessage.warning('请先统一各园区税点');return}if(productDetailTextLength(product.description)>5000){ElMessage.warning('商品详情文字不能超过 5000 字');return}if(!validBasic()||!product.parkIds.length||!(await hasUsableCover())||!hasProductDetail(product.description)||!validSupply(product.supply)||product.parkIds.some(id=>!product.parks[id]||!validSupply(product.parks[id]))){ElMessage.warning('请补全商品及各园区信息，并检查商品主图是否可用');return}if(!validEditTarget())return;const existing=store.products.find(item=>item.id===product.id);try{if(existing&&existing.status!=='draft'){store.submitEdit(product)}else{product.status='reviewing';product.parkStatuses=Object.fromEntries(product.parkIds.map(id=>[id,'reviewing']));product.approvalLog=submitApprovals(product,'上架审批',commerce.joinedParks.filter(p=>product.parkIds.includes(p.id)));store.save(product)}savedState.value=JSON.stringify(product);step.value=5}catch(error){ElMessage.error(error instanceof Error?error.message:'提交失败，请重试')}}

</script>
<template>
<div class="biz-page editor">
<section v-if="missingProduct" class="submitted"><h2>未找到该商品</h2><p>商品可能已删除或不属于当前供应商。</p><div class="submitted-actions"><ElButton type="primary" @click="router.push('/product')">返回商品管理</ElButton></div></section>
<template v-else>
  <header class="editor-top"><div class="editor-top-inner">
    <div class="editor-heading"><div><h1>{{route.params.id?'编辑商品':'发布商品'}}</h1></div><ElButton v-if="step<5" @click="fillDemo">演示填入</ElButton></div>
    <nav class="editor-steps" aria-label="发布商品步骤"><div v-for="(label,i) in headings" :key="label" class="editor-step" :class="{active:step===i+1,done:step>i+1}" :aria-current="step===i+1?'step':undefined"><button v-if="route.params.id && step<5 && i<4" type="button" class="step-link" @click="step=i+1"><span class="editor-step-dot"><Check v-if="step>i+1" :size="15"/><template v-else>{{i+1}}</template></span><span>{{label}}</span></button><template v-else><span class="editor-step-dot"><Check v-if="step>i+1" :size="15"/><template v-else>{{i+1}}</template></span><span>{{label}}</span></template><i v-if="i<headings.length-1"/></div></nav>
  </div></header>
  <div ref="scrollArea" class="editor-scroll"><div class="editor-content">
<section v-if="step===1" class="panel"><h2>基础信息</h2><div class="biz-grid"><label class="biz-field">商品标题 <b class="required">*</b><ElInput v-model="product.name" maxlength="60" show-word-limit placeholder="请输入商品标题"/></label><label class="biz-field">商品类目 <b class="required">*</b><ElSelect v-model="product.category" placeholder="请选择入驻时填写的主营类目"><ElOption v-for="item in onboarding.draft.businessCategories" :key="item" :label="item" :value="item"/></ElSelect><small v-if="!onboarding.draft.businessCategories.length">请先在经营信息中填写主营类目</small></label><label class="biz-field">品牌 <b v-if="onboarding.draft.brands.length" class="required">*</b><ElSelect v-if="onboarding.draft.brands.length" v-model="product.brand" placeholder="请选择经营品牌"><ElOption v-for="brand in onboarding.draft.brands" :key="brand.id" :label="brand.name" :value="brand.name"/></ElSelect><small v-else>经营信息中暂无品牌，商品可不填写品牌</small></label><label class="biz-field">供应商 SKU <b class="required">*</b><ElInput v-model="product.sku" placeholder="请输入 SKU"/></label><label class="biz-field">商品型号<ElInput v-model="product.model" placeholder="填写商品型号"/></label><label class="biz-field">规格 <b class="required">*</b><ElInput v-model="product.spec" placeholder="填写规格"/></label><label class="biz-field">税收分类编码 <b class="required">*</b><ElInput v-model="product.taxCode" placeholder="填写税收分类编码"/></label><label class="biz-field">商品合同名称（选填）<ElInput v-model="product.contractName" placeholder="用于合同展示"/></label><label class="biz-field">计量单位 <b class="required">*</b><ElInput v-model="product.unit" placeholder="如件、箱"/></label></div><div class="attrs"><div class="attrs-head"><div><h3>商品属性</h3><p class="hint">可自定义添加多条属性，例如材质：ABS 塑料、颜色：白色。</p></div><ElButton @click="addAttribute">添加属性</ElButton></div><div v-for="(a,i) in product.attrs" :key="a.id" class="attr-row"><ElInput v-model="a.name" placeholder="属性名称，如：材质"/><ElInput v-model="a.value" placeholder="属性值，如：ABS 塑料"/><ElButton text type="danger" @click="product.attrs?.splice(i,1)">删除</ElButton></div><p v-if="!product.attrs?.length" class="hint">暂无商品属性，可添加多条名称与属性值。</p></div><div class="sales-area"><label class="biz-field">销售区域（选填）<ElCascader :model-value="salesRegions" :options="salesRegionOptions" :props="{ multiple: true, emitPath: true, checkStrictly: true }" clearable filterable collapse-tags collapse-tags-tooltip placeholder="搜索并选择省 / 市，可多选" style="width:100%" @change="changeSalesRegions"/><small>可选择全国，或按地区选择；未选择表示不限制销售区域。</small></label></div></section>
<template v-if="step===2"><div v-if="route.params.id && original && original.status!=='draft'" class="biz-note warn">已发布商品的税点可在此统一调整并提交审核；其他供货、价格与园区请通过商品列表中的相应操作调整。</div><section class="panel"><h2>默认供货与价格</h2><p class="hint">税点在此统一设置，勾选批量同步后应用至全部已选发布园区；其他默认值不会自动覆盖园区配置。</p><SupplyFields :value="product.supply"/></section><section class="panel"><h2>物流信息</h2><ElSelect v-model="product.freightMode"><ElOption label="免运费" value="免运费"/></ElSelect></section><section class="panel"><h2>发布园区</h2><p class="hint">选择园区并展开调整独立配置；取消选择不会清除已填写的园区信息。</p><div class="park-actions"><ElButton size="small" @click="product.parkIds=parks.map(p=>p.id)">全选</ElButton><ElButton size="small" @click="product.parkIds=[]">清空</ElButton></div><ElCheckboxGroup v-model="product.parkIds" class="park-list"><ElCheckbox v-for="p in parks" :key="p.id" :value="p.id">{{p.name}}</ElCheckbox></ElCheckboxGroup><p v-if="!parks.length" class="hint">暂无已加入园区，请先前往我的园区。</p><div v-if="taxMismatch" class="tax-mismatch"><span>已有园区税点与统一税点不同，请确认是否统一为 {{product.supply.tax}}%。</span><ElButton size="small" @click="applyUnifiedTax">统一税点</ElButton></div><div v-if="product.parkIds.length" class="sync"><strong>批量同步默认值</strong><p>税点统一同步至全部已选发布园区；其他勾选字段同步至下方目标园区，优惠类型与对应数值作为一组同步。</p><ElCheckboxGroup v-model="syncFields"><ElCheckbox v-for="[key,label] in fields" :key="key" :value="key">{{label}}</ElCheckbox></ElCheckboxGroup><div class="sync-target"><span>目标园区</span><ElCheckboxGroup v-model="syncParks"><ElCheckbox v-for="p in parks.filter(p=>product.parkIds.includes(p.id))" :key="p.id" :value="p.id">{{p.name}}</ElCheckbox></ElCheckboxGroup><ElButton type="primary" plain @click="sync">同步所选字段</ElButton></div></div><div v-for="p in parks.filter(p=>product.parkIds.includes(p.id))" :key="p.id" class="park-card"><button class="park-head" @click="toggle(p.id)"><strong>{{p.name}}</strong><span>{{expanded.includes(p.id)?'收起':'展开调整'}} <component :is="expanded.includes(p.id)?ChevronDown:ChevronRight" :size="16"/></span></button><div v-if="expanded.includes(p.id)&&product.parks[p.id]" class="park-body"><SupplyFields :value="product.parks[p.id]" tax-locked/></div></div></section></template>
<section v-if="step===3" class="panel"><h2>图文详情</h2><ProductMediaFields v-model:cover="product.cover" v-model:images="product.images"/><label class="biz-field">产品特点<ElInput v-model="product.features" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="简要描述卖点、材质和适用场景"/></label><label class="biz-field">商品详情 <b class="required">*</b><ProductRichText v-model="product.description"/></label></section>
<ProductSubmitPreview v-if="step===4" :product="product" :parks="parks" /><section v-if="step===5" class="submitted"><div class="submitted-icon"><CircleCheck :size="34" :stroke-width="1.8" /></div><h2>商品已提交，等待审核</h2><p>商品资料已提交，审核通过后将在对应园区上架。</p><div class="submitted-flow"><span class="done"><CircleCheck :size="17"/>提交成功</span><i/><span class="current">园区审核</span><i/><span>审核通过</span></div><div class="submitted-actions"><ElButton type="primary" @click="router.push('/product')"><ArrowLeft :size="15"/>返回商品管理</ElButton><ElButton @click="continuePublish">继续发布</ElButton></div></section>
  </div></div>
  <footer v-if="step<5" class="editor-footer"><div class="editor-footer-inner"><div class="editor-footer-left"><button type="button" class="editor-link" @click="router.push('/product')"><ArrowLeft :size="15"/>返回商品管理</button><button type="button" class="editor-link save-link" @click="save"><Save :size="15"/>保存草稿</button></div><div class="editor-footer-right"><ElButton v-if="step>1" @click="step--"><ArrowLeft :size="15"/>上一步</ElButton><ElButton v-if="step<4" type="primary" @click="next">下一步<ArrowRight :size="15"/></ElButton><ElButton v-else type="primary" @click="submit">提交审核<ArrowRight :size="15"/></ElButton></div></div></footer>
</template>
</div></template>
